argv:
$ErrorActionPreference='Stop';
$repo='E:\WebAIBridge';
$data='E:\WebAIBridge\app\data';
$git=(Get-Command git.exe -CommandType Application -ErrorAction Stop | Select-Object -First 1).Path;
$head=((@(& $git -C $repo rev-parse HEAD)) -join [Environment]::NewLine).Trim();
$branch=((@(& $git -C $repo branch --show-current)) -join [Environment]::NewLine).Trim();
$dirty=@(& $git -C $repo status --porcelain);
$names=@('projects-live-control-plane-cutover-r42.json','projects-live-control-plane-cutover-r42-reconcile.json','projects-live-control-plane-r41.json','projects-operation-ledger-r41.json','supervisor-watchdog.json','state.json');
$out=@();
foreach($n in $names){
  $p=Join-Path $data $n;
  if(Test-Path -LiteralPath $p){
    $txt=((Get-Content -LiteralPath $p -Raw) -as [string]);
    if($null -eq $txt){$txt=''}
    $out += [pscustomobject]@{name=$n;exists=$true;length=$txt.Length;sha256=(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant();preview=$txt.Substring(0,[Math]::Min(9000,$txt.Length))}
  }else{$out += [pscustomobject]@{name=$n;exists=$false}}
}
$backs=@();
$br=Join-Path $data 'backups';
if(Test-Path $br){$backs=@(Get-ChildItem $br -Directory -Filter 'r42-cutover-*' | Sort-Object LastWriteTime -Descending | Select-Object -First 8 Name,FullName,LastWriteTime)}
[pscustomobject]@{head=$head;branch=$branch;detached=[string]::IsNullOrWhiteSpace($branch);dirty=@($dirty);files=$out;backups=$backs}|ConvertTo-Json -Depth 7 -Compress
